{"file_path":"src/errors.js","content":"/** A failure that the command reports on standard error before exiting 2. */
export class ElectionError extends Error {
  constructor(message) {
    super(message)
    this.name = 'ElectionError'
  }
}

/** Fails with a message carrying the one-based number of the offending line. */
export function failAt(lineNumber, message) {
  throw new ElectionError(`line ${lineNumber}: ${message}`)
}

/** Fails with a message that names no particular line. */
export function fail(message) {
  throw new ElectionError(message)
}
"}

