{"file_path":"src/parse.js","content":"import { fail, failAt } from './errors.js'

const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

/**
 * Reads an election from the text of standard input. Returns the declared
 * candidates in declaration order and the ballots, each with its multiplicity
 * and its ranking from most to least preferred.
 */
export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const declared = new Set()
  const ballots = []

  for (let index = 0; index < lines.length; index += 1) {
    const lineNumber = index + 1
    const line = lines[index].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'candidates') {
      if (candidates !== null) {
        failAt(lineNumber, 'candidates must be declared once, before any ballot')
      }
      const names = words.slice(1)
      if (names.length === 0) failAt(lineNumber, 'expected candidates <name>...')
      for (const name of names) {
        if (!NAME.test(name)) failAt(lineNumber, `invalid candidate name ${name}`)
        if (declared.has(name)) failAt(lineNumber, `candidate ${name} is declared twice`)
        declared.add(name)
      }
      candidates = names
      continue
    }

    if (directive === 'ballot') {
      if (candidates === null) {
        failAt(lineNumber, 'candidates must be declared once, before any ballot')
      }
      if (words.length < 3) failAt(lineNumber, 'expected ballot <count> <candidate>...')
      const count = words[1]
      if (!COUNT.test(count)) failAt(lineNumber, 'count must be a positive integer')
      const ranking = words.slice(2)
      const seen = new Set()
      for (const name of ranking) {
        if (!declared.has(name)) failAt(lineNumber, `unknown candidate ${name}`)
        if (seen.has(name)) failAt(lineNumber, `candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: Number(count), ranking })
      continue
    }

    failAt(lineNumber, `unknown directive ${directive}`)
  }

  if (candidates === null) fail('no candidates')
  return { candidates, ballots }
}
"}

