{"file_path":"src/count.js","content":"/**
 * Runs the instant-runoff count. Returns the rounds that were counted and the
 * winner, or a null winner when the election ended without a majority.
 *
 * Each round holds a map from every candidate still continuing at its start to
 * the number of ballots that counted for them, the number of exhausted ballots,
 * the active total, and the candidate it eliminated, if any.
 */
export function countElection({ candidates, ballots }) {
  let continuing = candidates.slice()
  const rounds = []

  for (;;) {
    const counts = new Map(continuing.map((name) => [name, 0]))
    const still = new Set(continuing)
    let exhausted = 0
    let active = 0

    for (const ballot of ballots) {
      const choice = ballot.ranking.find((name) => still.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        counts.set(choice, counts.get(choice) + ballot.count)
        active += ballot.count
      }
    }

    const round = { counts, exhausted, active, eliminated: null }
    rounds.push(round)

    if (active === 0) return { rounds, winner: null }

    const winner = continuing.find((name) => counts.get(name) * 2 > active)
    if (winner !== undefined) return { rounds, winner }

    const loser = chooseEliminated(continuing, rounds)
    round.eliminated = loser
    continuing = continuing.filter((name) => name !== loser)
  }
}

/**
 * Picks the candidate to eliminate: the fewest votes in the latest round, ties
 * broken by looking back over the rounds counted so far from the first onwards,
 * and finally by the name that sorts last by code point.
 */
function chooseEliminated(continuing, rounds) {
  const latest = rounds[rounds.length - 1].counts
  let survivors = fewest(continuing, (name) => latest.get(name))

  while (survivors.length > 1) {
    let narrowed = false
    for (const round of rounds) {
      const votes = survivors.map((name) => round.counts.get(name))
      if (votes.some((value) => value !== votes[0])) {
        survivors = fewest(survivors, (name) => round.counts.get(name))
        narrowed = true
        break
      }
    }
    if (!narrowed) break
  }

  if (survivors.length === 1) return survivors[0]
  return survivors.slice().sort(compareByCodePoint)[survivors.length - 1]
}

function fewest(names, votesOf) {
  let best = Infinity
  for (const name of names) best = Math.min(best, votesOf(name))
  return names.filter((name) => votesOf(name) === best)
}

export function compareByCodePoint(left, right) {
  const a = Array.from(left)
  const b = Array.from(right)
  const shared = Math.min(a.length, b.length)
  for (let index = 0; index < shared; index += 1) {
    const difference = a[index].codePointAt(0) - b[index].codePointAt(0)
    if (difference !== 0) return difference
  }
  return a.length - b.length
}
"}

