/** Renders the full report of every round, then the outcome. */
export function formatRounds({ rounds, winner }) {
  const lines = []
  rounds.forEach((round, index) => {
    const names = [...round.counts.keys()].sort((left, right) => {
      const difference = round.counts.get(right) - round.counts.get(left)
      return difference !== 0 ? difference : compareByCodePoint(left, right)
    })
    const entries = names.map((name) => `${name}=${round.counts.get(name)}`)
    entries.push(`exhausted=${round.exhausted}`)
    lines.push(`round ${index + 1}: ${entries.join(' ')}`)
    if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
  })
  lines.push(outcome(winner))
  return lines.map((line) => `${line}\n`).join('')
}

/** Renders how many rounds were counted, then the outcome. */
export function formatTally({ rounds, winner }) {
  return `rounds ${rounds.length}\n${outcome(winner)}\n`
}

function outcome(winner) {
  return winner === null ? 'no winner' : `winner ${winner}`
}
"}

